import pandas as pd
import numpy as np
import json
import time
import sys
from datetime import datetime
from gamspy import Container, Set, Parameter, Variable, Equation, Model, Sense, Sum, Ord

def gams_parameter_to_gamspy(gams_text):
    """Convert GAMS parameter format to GAMSPy format"""
    lines = gams_text.strip().split('\n')
    gamspy_data = []
    
    for line in lines:
        line = line.strip()
        if (not line or 
            line.startswith('Parameter') or
            line.startswith('parameter') or
            line.startswith('/') or
            line.endswith('/;') or
            line == '.../' or
            line == '/'):
            continue
        
        line = line.rstrip(',;/')
        parts = line.split()
        if len(parts) >= 2:
            try:
                index = parts[0]
                value = float(parts[1])
                gamspy_data.append((index, value))
            except ValueError:
                continue
    
    return gamspy_data

def setup_model():
    """Set up the complete microgrid optimization model"""
    print(f"[{datetime.now().strftime('%H:%M:%S')}] Setting up optimization model")

    m = Container()

    t = Set(m, name="t", records=[str(i) for i in range(1, 8761)], description="hours")
    op_modes = Set(m, name="op_modes", records=["ch", "dis"], description="operation modes")
    grid_modes = Set(m, name="grid_modes", records=["import", "export"], description="grid modes")

    n_households = Parameter(m, name="n_households", records=5000)
    max_grid_import = Parameter(m, name="max_grid_import", records=0.05)
    lifetime_microgrid = Parameter(m, name="lifetime_microgrid", records=20)

    Ccap_PV = Parameter(m, name="Ccap_PV", records=500000)
    Cop_PV = Parameter(m, name="Cop_PV", records=15000)
    Ccap_wind = Parameter(m, name="Ccap_wind", records=1200000)
    Cop_wind = Parameter(m, name="Cop_wind", records=25000)
    Ccap_BESS_MWh = Parameter(m, name="Ccap_BESS_MWh", records=150000)
    Cop_BESS = Parameter(m, name="Cop_BESS", records=25000)
    battery_duration = Parameter(m, name="battery_duration", records=4)
    daily_self_discharge_rate = Parameter(m, name="daily_self_discharge_rate", records=0.001)
    eta_BESS_ch = Parameter(m, name="eta_BESS_ch", records=0.95)
    eta_BESS_dis = Parameter(m, name="eta_BESS_dis", records=0.95)
    Ccap_H2_MW = Parameter(m, name="Ccap_H2_MW", records=1850000)
    Ccap_H2_MWh = Parameter(m, name="Ccap_H2_MWh", records=40000)
    Cop_H2_MW = Parameter(m, name="Cop_H2_MW", records=17000)
    eta_H2_ch = Parameter(m, name="eta_H2_ch", records=0.70)
    eta_H2_dis = Parameter(m, name="eta_H2_dis", records=0.55)
    max_annual_export_MWh = Parameter(m, name="max_annual_export_MWh", records=5000)
    
    distribution_loss_factor = Parameter(m, name="distribution_loss_factor", records=0.085, description="8.5% distribution losses")
    grid_interface_efficiency = Parameter(m, name="grid_interface_eff", records=0.975, description="2.5% grid interface losses")

    grid_connection_cost = Parameter(m, name="grid_connection_cost", records=500000, description="Base grid connection cost £")
    
    grid_code_cost_per_MW = Parameter(m, name="grid_code_cost_per_MW", records=30000, description="Grid code compliance cost £/MW")

    duos_capacity_charge = Parameter(m, name="duos_capacity_charge", records=28000, description="DUoS capacity charge £/MW/year (NW England)")

    tnuos_generation_charge = Parameter(m, name="tnuos_generation_charge", records=35000, description="TNUoS generation charge £/MW/year (NW England)")
    
    print(f"[{datetime.now().strftime('%H:%M:%S')}] Parameters created")
    print(f"[{datetime.now().strftime('%H:%M:%S')}] Converting GAMS data")

    solar_profile_data = gams_parameter_to_gamspy(solar_gams)
    wind_profile_data = gams_parameter_to_gamspy(wind_gams)
    demand_profile_data = gams_parameter_to_gamspy(demand_gams)
    I_price_data = gams_parameter_to_gamspy(import_price_gams)
    E_price_data = gams_parameter_to_gamspy(export_price_gams)

    solar_profile = Parameter(m, name="solar_profile", domain=t, records=solar_profile_data)
    wind_profile = Parameter(m, name="wind_profile", domain=t, records=wind_profile_data)
    demand_profile = Parameter(m, name="demand_profile", domain=t, records=demand_profile_data)
    I_price = Parameter(m, name="I_price", domain=t, records=I_price_data)
    E_price = Parameter(m, name="E_price", domain=t, records=E_price_data)

    max_demand = Parameter(m, name="max_demand")
    total_annual_demand = Parameter(m, name="total_annual_demand")
    
    max_demand_value = max([record[1] for record in demand_profile_data]) * 5000
    total_demand_value = sum([record[1] for record in demand_profile_data]) * 5000
    max_demand.assign = max_demand_value
    total_annual_demand.assign = total_demand_value
    
    print(f"[{datetime.now().strftime('%H:%M:%S')}] Data loaded: {len(solar_profile_data)} hours")

    cost = Variable(m, name="cost", type="free", description="Total system cost")
    x_PV = Variable(m, name="x_PV", type="positive", description="PV capacity (MW)")
    x_wind = Variable(m, name="x_wind", type="positive", description="wind capacity (MW)")
    x_BESS = Variable(m, name="x_BESS", type="positive", description="BESS power (MW)")
    x_H2_power = Variable(m, name="x_H2_power", type="positive", description="H2 power capacity (MW) - electrolyser / fuel cell")
        
    SOC_BESS = Variable(m, name="SOC_BESS", type="positive", domain=t, description="Battery SOC (MWh)")
    SOC_H2 = Variable(m, name="SOC_H2", type="positive", domain=t, description="H2 SOC (MWh)")
    x_H2_storage = Variable(m, name="x_H2_storage", type="positive", description="H2 storage capacity (MWh)")
    
    P_BESS_op = Variable(m, name="P_BESS_op", type="sos1", domain=[t, op_modes], description="Battery Power Flow (MW)")
    P_H2_op = Variable(m, name="P_H2_op", type="sos1", domain=[t, op_modes], description="H2 Power Flow (MW)")
    grid_op = Variable(m, name="grid_op", type="sos1", domain=[t, grid_modes], description="Grid Flow (MW)")
    
    total_generation_capacity = Variable(m, name="total_generation_capacity", type="positive", description="Total generation capacity (MW)")

    print(f"[{datetime.now().strftime('%H:%M:%S')}] Variables created")

    total_gen_capacity_eq = Equation(m, name="total_gen_capacity_eq")
    total_gen_capacity_eq[...] = total_generation_capacity == x_PV + x_wind    

    H2_max_SOC_constraint = Equation(m, name="H2_max_SOC_constraint", domain=t)
    H2_max_SOC_constraint[t] = SOC_H2[t] <= x_H2_storage

    total_cost = Equation(m, name="total_cost")
    total_cost[...] = (
        cost ==
        Ccap_PV * x_PV + Cop_PV * x_PV * lifetime_microgrid +
        Ccap_wind * x_wind + Cop_wind * x_wind * lifetime_microgrid +
        Ccap_BESS_MWh * 2 * (battery_duration * x_BESS) +
        Cop_BESS * x_BESS * lifetime_microgrid +
        Ccap_H2_MW * x_H2_power + Ccap_H2_MWh * x_H2_storage +
        Cop_H2_MW * x_H2_power * lifetime_microgrid +
        grid_connection_cost +
        grid_code_cost_per_MW * total_generation_capacity +
        (duos_capacity_charge * total_generation_capacity + 
         tnuos_generation_charge * total_generation_capacity) * lifetime_microgrid +
        Sum(t, grid_op[t, "import"] * I_price[t]) * lifetime_microgrid -
        Sum(t, (grid_op[t, "export"] * grid_interface_efficiency) * E_price[t]) * lifetime_microgrid
    )
    
    power_balance = Equation(m, name="power_balance", domain=t)
    power_balance[t] = (
        x_PV * solar_profile[t] + x_wind * wind_profile[t] +
        P_BESS_op[t, "dis"] + P_H2_op[t, "dis"] + grid_op[t, "import"] ==
        demand_profile[t] * n_households / (1 - distribution_loss_factor) + P_BESS_op[t, "ch"] +
        P_H2_op[t, "ch"] + grid_op[t, "export"]
    )
    
    BESS_cyclical_SOC = Equation(m, name="BESS_cyclical_SOC")
    BESS_cyclical_SOC[...] = SOC_BESS["1"] == SOC_BESS["8760"]
    
    H2_cyclical_SOC = Equation(m, name="H2_cyclical_SOC")
    H2_cyclical_SOC[...] = SOC_H2["1"] == SOC_H2["8760"]    

    BESS_SOC_dynamics = Equation(m, name="BESS_SOC_dynamics", domain=t)
    BESS_SOC_dynamics[t] = (
        SOC_BESS[t] ==
        (SOC_BESS[t.lag(1)].where[Ord(t) > 1] + 
        SOC_BESS["8760"].where[Ord(t) == 1]) *
        (1 - daily_self_discharge_rate/24) +
        eta_BESS_ch * P_BESS_op[t, "ch"] -
        P_BESS_op[t, "dis"] / eta_BESS_dis
    )
    
    BESS_final_SOC = Equation(m, name="BESS_final_SOC")
    BESS_final_SOC[...] = SOC_BESS["8760"] >= 0.5 * battery_duration * x_BESS
    
    BESS_SOC_capacity_limit = Equation(m, name="BESS_SOC_capacity_limit", domain=t)
    BESS_SOC_capacity_limit[t] = SOC_BESS[t] <= battery_duration * x_BESS
    
    BESS_power_limit = Equation(m, name="BESS_power_limit", domain=t)
    BESS_power_limit[t] = P_BESS_op[t, "ch"] + P_BESS_op[t, "dis"] <= x_BESS
    
    H2_SOC_dynamics = Equation(m, name="H2_SOC_dynamics", domain=t)
    H2_SOC_dynamics[t] = (
        SOC_H2[t] ==
        (SOC_H2[t.lag(1)].where[Ord(t) > 1] +
        SOC_H2["8760"].where[Ord(t) == 1]) +
        eta_H2_ch * P_H2_op[t, "ch"] -
        P_H2_op[t, "dis"] / eta_H2_dis
    )
    
    H2_power_limit = Equation(m, name="H2_power_limit", domain=t)
    H2_power_limit[t] = P_H2_op[t, "ch"] + P_H2_op[t, "dis"] <= x_H2_power
    
    grid_import_annual_limit = Equation(m, name="grid_import_annual_limit")
    grid_import_annual_limit[...] = Sum(t, grid_op[t, "import"]) <= max_grid_import * total_annual_demand
    
    grid_export_annual_limit = Equation(m, name="grid_export_annual_limit")
    grid_export_annual_limit[...] = Sum(t, grid_op[t, "export"]) <= max_annual_export_MWh
    
    print(f"[{datetime.now().strftime('%H:%M:%S')}] Equations created")

    microgrid = Model(
        m,
        name="microgrid",
        equations=m.getEquations(),
        problem="MIP",
        sense=Sense.MIN,
        objective=cost,
    )
    
    print(f"[{datetime.now().strftime('%H:%M:%S')}] Model setup complete")
    
    return (microgrid, cost, x_PV, x_wind, x_BESS, x_H2_power, x_H2_storage, grid_op, demand_profile_data, total_demand_value, solar_profile_data, wind_profile_data, I_price_data, E_price_data, P_BESS_op, P_H2_op, SOC_BESS, SOC_H2, distribution_loss_factor, grid_interface_efficiency, total_generation_capacity, grid_connection_cost, grid_code_cost_per_MW, duos_capacity_charge, tnuos_generation_charge, lifetime_microgrid)

def solve_microgrid():
    """Solve the microgrid optimization problem"""
    try:
        microgrid, cost, x_PV, x_wind, x_BESS, x_H2_power, x_H2_storage, grid_op, demand_profile_data, total_demand_value, solar_profile_data, wind_profile_data, I_price_data, E_price_data, P_BESS_op, P_H2_op, SOC_BESS, SOC_H2, distribution_loss_factor, grid_interface_efficiency, total_generation_capacity, grid_connection_cost, grid_code_cost_per_MW, duos_capacity_charge, tnuos_generation_charge, lifetime_microgrid = setup_model()
        
        print(f"Problem type: {microgrid.problem}")

        print(f"[{datetime.now().strftime('%H:%M:%S')}] Starting optimization")
        print("Solver settings: 0.3% optimality gap")
        
        start_time = time.time()
        
        microgrid.solve(solver="CPLEX", solver_options={
            "epgap": 0.003
        })
        
        end_time = time.time()
        solve_time = end_time - start_time
        
        print(f"[{datetime.now().strftime('%H:%M:%S')}] Optimization completed in {solve_time:.2f} seconds")

        results = {
            'solve_time_seconds': solve_time,
            'solve_time_hours': solve_time / 3600,
            'model_status': str(microgrid.status),
            'objective_gbp': cost.toValue(),
            'objective_million_gbp': cost.toValue() / 1e6,
            'pv_capacity_mw': x_PV.toValue(),
            'wind_capacity_mw': x_wind.toValue(),
            'bess_power_mw': x_BESS.toValue(),
            'bess_energy_mwh': 4 * x_BESS.toValue(),
            'h2_power_mw': x_H2_power.toValue(),
            'h2_energy_mwh': x_H2_storage.toValue(),
            'timestamp': datetime.now().isoformat()
        }

        total_import_mwh = 0
        total_export_mwh = 0

        if hasattr(grid_op, 'records') and grid_op.records is not None and not grid_op.records.empty:
            import_records = grid_op.records[grid_op.records['grid_modes'] == 'import']
            if not import_records.empty:
                total_import_mwh = import_records['level'].sum()

            export_records = grid_op.records[grid_op.records['grid_modes'] == 'export']
            if not export_records.empty:
                total_export_mwh = export_records['level'].sum()

        import_percentage = (total_import_mwh / total_demand_value) * 100 if total_demand_value > 0 else 0

        export_revenue = 0
        if hasattr(grid_op, 'records') and grid_op.records is not None:
            for i, export_price in enumerate(E_price_data, 1):
                hour_str = str(i)
                hour_export = grid_op.records[
                    (grid_op.records['t'] == hour_str) & 
                    (grid_op.records['grid_modes'] == 'export')
                ]
                if not hour_export.empty:
                    export_revenue += float(hour_export['level'].iloc[0]) * grid_interface_efficiency.toValue() * float(export_price[1])
  
        import_cost = 0
        if hasattr(grid_op, 'records') and grid_op.records is not None:
            for i, import_price in enumerate(I_price_data, 1):
                hour_str = str(i)
                hour_import = grid_op.records[
                    (grid_op.records['t'] == hour_str) & 
                    (grid_op.records['grid_modes'] == 'import')
                ]
                if not hour_import.empty:
                    import_cost += float(hour_import['level'].iloc[0]) * float(import_price[1])


        results.update({
            'total_import_mwh': total_import_mwh,
            'total_export_mwh': total_export_mwh,
            'import_percentage': import_percentage,
            'export_revenue_gbp': export_revenue,
            'import_cost_gbp': import_cost,
            'net_grid_cost_gbp': import_cost - export_revenue
        })

        total_gen_cap = total_generation_capacity.toValue()
        
        connection_costs = {
            'grid_connection_base_gbp': grid_connection_cost.toValue(),
            'grid_code_compliance_gbp': grid_code_cost_per_MW.toValue() * total_gen_cap,
            'annual_capacity_charges_gbp': (duos_capacity_charge.toValue() + tnuos_generation_charge.toValue()) * total_gen_cap * lifetime_microgrid.toValue(),
        }
        
        connection_costs['total_connection_costs_gbp'] = sum(connection_costs.values())
        connection_costs['total_connection_costs_million_gbp'] = connection_costs['total_connection_costs_gbp'] / 1e6
        
        results.update(connection_costs)

        print("Creating detailed hourly analysis")

        hourly_data = []
        for i in range(1,8761):
            try:            

                hour_str = str(i)

                solar_factor = next((float(r[1]) for r in solar_profile_data if r[0] == hour_str), 0)
                wind_factor = next((float(r[1]) for r in wind_profile_data if r[0] == hour_str), 0)
                demand_factor = next((float(r[1]) for r in demand_profile_data if r[0] == hour_str), 0)

                pv_gen = x_PV.toValue() * solar_factor
                wind_gen = x_wind.toValue() * wind_factor
                demand = demand_factor * 5000
                
                demand_with_losses = demand / (1 - distribution_loss_factor.toValue())

                grid_import = 0
                grid_export = 0

                if hasattr(grid_op,'records') and grid_op.records is not None and not grid_op.records.empty:
                    hour_grid_data = grid_op.records[grid_op.records['t'] == hour_str]

                    if not hour_grid_data.empty:
                        import_rows = hour_grid_data[hour_grid_data['grid_modes'] == 'import']
                        export_rows = hour_grid_data[hour_grid_data['grid_modes'] == 'export']

                        if not import_rows.empty:
                            grid_import = float(import_rows['level'].iloc[0])
                        if not export_rows.empty:
                            grid_export = float(export_rows['level'].iloc[0])

                grid_export_with_losses = grid_export * grid_interface_efficiency.toValue()

                bess_charge = 0
                bess_discharge = 0
                if hasattr(P_BESS_op, 'records') and P_BESS_op.records is not None and not P_BESS_op.records.empty:
                    hour_bess_data = P_BESS_op.records[P_BESS_op.records['t'] == hour_str]
                    if not hour_bess_data.empty:
                        charge_rows = hour_bess_data[hour_bess_data['op_modes'] == 'ch']
                        discharge_rows = hour_bess_data[hour_bess_data['op_modes'] == 'dis']
                        
                        if not charge_rows.empty:
                            bess_charge = float(charge_rows['level'].iloc[0])
                        if not discharge_rows.empty:
                            bess_discharge = float(discharge_rows['level'].iloc[0])

                h2_charge = 0
                h2_discharge = 0
                if hasattr(P_H2_op, 'records') and P_H2_op.records is not None and not P_H2_op.records.empty:
                    hour_h2_data = P_H2_op.records[P_H2_op.records['t'] == hour_str]
                    if not hour_h2_data.empty:
                        charge_rows = hour_h2_data[hour_h2_data['op_modes'] == 'ch']
                        discharge_rows = hour_h2_data[hour_h2_data['op_modes'] == 'dis']
                        
                        if not charge_rows.empty:
                            h2_charge = float(charge_rows['level'].iloc[0])
                        if not discharge_rows.empty:
                            h2_discharge = float(discharge_rows['level'].iloc[0])

                bess_soc = 0
                h2_soc = 0
                if hasattr(SOC_BESS, 'records') and SOC_BESS.records is not None and not SOC_BESS.records.empty:
                    hour_bess_soc = SOC_BESS.records[SOC_BESS.records['t'] == hour_str]
                    if not hour_bess_soc.empty:
                        bess_soc = float(hour_bess_soc['level'].iloc[0])
                
                if hasattr(SOC_H2, 'records') and SOC_H2.records is not None and not SOC_H2.records.empty:
                    hour_h2_soc = SOC_H2.records[SOC_H2.records['t'] == hour_str]
                    if not hour_h2_soc.empty:
                        h2_soc = float(hour_h2_soc['level'].iloc[0])

                total_supply = pv_gen + wind_gen + bess_discharge + h2_discharge + grid_import
        
                total_demand_side = demand_with_losses + bess_charge + h2_charge + grid_export

                hourly_data.append({
                    'hour': i,
                    'pv_gen_mw': pv_gen,
                    'wind_gen_mw': wind_gen,
                    'total_gen_mw': pv_gen + wind_gen,
                    'demand_mw': demand,
                    'demand_with_losses_mw': demand_with_losses,
                    'grid_import_mw': grid_import,
                    'grid_export_mw': grid_export,
                    'grid_export_paid_for_mw': grid_export_with_losses,
                    'bess_charge_mw': bess_charge,
                    'bess_discharge_mw': bess_discharge,
                    'bess_soc_mwh': bess_soc,
                    'h2_charge_mw': h2_charge,
                    'h2_discharge_mw': h2_discharge,
                    'h2_soc_mwh': h2_soc,
                    'total_supply_mw': total_supply,
                    'total_demand_side_mw': total_demand_side
                })

            except Exception as e:
                print(f"Error processing hour {i}: {e}")
                if i <= 5:
                    import traceback
                    traceback.print_exc()                
                continue

        if hourly_data:
            hourly_df = pd.DataFrame(hourly_data)
            hourly_df.to_csv("hourly_analysis.csv", index=False)
            print(f"Saved hourly analysis for {len(hourly_data)} hours to hourly_analysis.csv")     
        else:
            print("No hourly data was successfully processed!")

        for key, value in results.items():
            try:
                json.dumps(value)
            except TypeError as e:
                print(f"Cannot serialize: {key} = {type(value)} - {e}")

        with open('microgrid_results.json', 'w') as f:
            json.dump(results, f, indent=2)
        
        results_df = pd.DataFrame([results])
        results_df.to_csv('microgrid_results.csv', index=False)

        print("\n" + "="*60)
        print("MICROGRID OPTIMIZATION RESULTS")
        print("="*60)
        print(f"Total Cost: £{results['objective_gbp']:,.0f} ({results['objective_million_gbp']:.2f} M£)")
        
        return results

    except Exception as e:
        print(f"Error in solve_microgrid: {e}")
        import traceback
        traceback.print_exc()
        return {'error': str(e), 'status': 'FAILED'}

